CREATE TABLE IF NOT EXISTS session_roots (
  root_branch_id TEXT PRIMARY KEY REFERENCES chat_branches(branch_id),
  owner_user_id TEXT NOT NULL REFERENCES users(id),
  policy TEXT NOT NULL DEFAULT 'private' CHECK (policy = 'private'),
  created_at TEXT NOT NULL
) STRICT;
CREATE INDEX IF NOT EXISTS idx_session_roots_owner ON session_roots(owner_user_id);
CREATE TABLE IF NOT EXISTS account_home_events (
  id TEXT PRIMARY KEY,
  actor_user_id TEXT NOT NULL REFERENCES users(id),
  target_user_id TEXT NOT NULL REFERENCES users(id),
  previous_home_chat_jid TEXT,
  target_branch_id TEXT NOT NULL,
  created_at TEXT NOT NULL
) STRICT;
CREATE TRIGGER IF NOT EXISTS session_root_owner_immutable
  BEFORE UPDATE OF root_branch_id, owner_user_id ON session_roots
  WHEN NEW.root_branch_id != OLD.root_branch_id OR NEW.owner_user_id != OLD.owner_user_id
  BEGIN SELECT RAISE(ABORT, 'Session root ownership is immutable'); END;
CREATE TRIGGER IF NOT EXISTS session_home_root_no_archive
  BEFORE UPDATE OF archived_at ON chat_branches
  WHEN NEW.archived_at IS NOT NULL AND EXISTS (
    SELECT 1 FROM session_roots r JOIN users u ON u.id = r.owner_user_id
    WHERE r.root_branch_id = OLD.branch_id AND u.home_chat_jid = OLD.chat_jid
  )
  BEGIN SELECT RAISE(ABORT, 'Assign another owned home root before archiving'); END;
CREATE TRIGGER IF NOT EXISTS session_home_follows_root_jid
  AFTER UPDATE OF chat_jid ON chat_branches WHEN NEW.chat_jid != OLD.chat_jid
  BEGIN
    UPDATE users SET home_chat_jid = NEW.chat_jid
    WHERE home_chat_jid = OLD.chat_jid AND id IN (
      SELECT owner_user_id FROM session_roots WHERE root_branch_id = OLD.branch_id
    );
  END;
CREATE TRIGGER IF NOT EXISTS session_owned_branch_no_delete
  BEFORE DELETE ON chat_branches WHEN EXISTS (
    SELECT 1 FROM session_roots WHERE root_branch_id = OLD.branch_id
  )
  BEGIN SELECT RAISE(ABORT, 'Owned root deletion requires explicit ownership cleanup'); END;

CREATE TABLE IF NOT EXISTS family_media_uploads (
    media_id INTEGER PRIMARY KEY REFERENCES media(id),
    owner_user_id TEXT NOT NULL REFERENCES users(id),
    login_session_id TEXT NOT NULL,
    created_at TEXT NOT NULL
  ) STRICT;
  CREATE INDEX IF NOT EXISTS idx_family_media_uploads_owner_created
    ON family_media_uploads(owner_user_id,created_at,media_id);
  CREATE TRIGGER IF NOT EXISTS family_media_upload_identity_immutable
    BEFORE UPDATE ON family_media_uploads
    BEGIN SELECT RAISE(ABORT,'Family media upload identity is immutable'); END;

CREATE TABLE IF NOT EXISTS operator_recovery_events (
      id TEXT PRIMARY KEY, target_user_id TEXT NOT NULL REFERENCES users(id),
      method TEXT NOT NULL CHECK(method IN ('totp','passkey')), origin TEXT NOT NULL, created_at TEXT NOT NULL
    ) STRICT;

CREATE TRIGGER IF NOT EXISTS user_totp_registration_logout
      AFTER DELETE ON web_sessions BEGIN
        DELETE FROM user_totp_registrations WHERE user_id=OLD.user_id AND session_id=OLD.session_id;
      END;

CREATE TABLE IF NOT EXISTS user_tool_restrictions (
    user_id TEXT PRIMARY KEY REFERENCES users(id),
    denied_tools TEXT NOT NULL,
    revision INTEGER NOT NULL CHECK (revision >= 1)
  ) STRICT;
  CREATE TABLE IF NOT EXISTS user_tool_restriction_events (
    id TEXT PRIMARY KEY, actor_user_id TEXT NOT NULL REFERENCES users(id), target_user_id TEXT NOT NULL REFERENCES users(id),
    previous_denied TEXT NOT NULL, next_denied TEXT NOT NULL, revision INTEGER NOT NULL, created_at TEXT NOT NULL
  ) STRICT;

CREATE TABLE IF NOT EXISTS user_avatars (
    user_id TEXT PRIMARY KEY REFERENCES users(id),
    revision INTEGER NOT NULL CHECK (revision >= 1),
    image BLOB CHECK (image IS NULL OR length(image) BETWEEN 1 AND 262144),
    updated_at TEXT NOT NULL
  ) STRICT;

CREATE TABLE IF NOT EXISTS user_model_defaults (
    user_id TEXT PRIMARY KEY REFERENCES users(id), revision INTEGER NOT NULL CHECK(revision >= 1),
    model TEXT, thinking_level TEXT, updated_at TEXT NOT NULL,
    CHECK(model IS NOT NULL OR thinking_level IS NULL)
  ) STRICT;

CREATE TABLE IF NOT EXISTS family_task_admissions (
    owner_user_id TEXT NOT NULL REFERENCES users(id),
    request_id TEXT NOT NULL,
    grant_id TEXT NOT NULL UNIQUE REFERENCES family_scheduled_grants(id),
    input_hash TEXT NOT NULL CHECK(length(input_hash)=64),
    login_session_id TEXT NOT NULL,
    created_at TEXT NOT NULL,
    PRIMARY KEY(owner_user_id,request_id)
  ) STRICT;
  CREATE INDEX IF NOT EXISTS family_scheduled_grants_owner_recent ON family_scheduled_grants(owner_user_id,created_at DESC,id DESC);
  CREATE TRIGGER IF NOT EXISTS family_task_admission_immutable BEFORE UPDATE ON family_task_admissions
    BEGIN SELECT RAISE(ABORT,'Task admission is immutable'); END;
  CREATE TRIGGER IF NOT EXISTS family_task_admission_no_delete BEFORE DELETE ON family_task_admissions
    BEGIN SELECT RAISE(ABORT,'Task admission cannot be replayed'); END;

CREATE TABLE IF NOT EXISTS family_scheduled_dispatches (
    execution_id TEXT PRIMARY KEY REFERENCES family_scheduled_executions(id),
    started_at INTEGER NOT NULL
  ) STRICT;
  CREATE TRIGGER IF NOT EXISTS family_scheduled_dispatch_immutable BEFORE UPDATE ON family_scheduled_dispatches
    BEGIN SELECT RAISE(ABORT,'Scheduled dispatch is immutable'); END;
  CREATE TRIGGER IF NOT EXISTS family_scheduled_dispatch_no_delete BEFORE DELETE ON family_scheduled_dispatches
    BEGIN SELECT RAISE(ABORT,'Scheduled dispatch cannot be replayed'); END;

CREATE TABLE IF NOT EXISTS family_scheduled_expiries (
    execution_id TEXT PRIMARY KEY REFERENCES family_scheduled_executions(id),
    created_at INTEGER NOT NULL CHECK(created_at>=0)
  ) STRICT;
  CREATE TRIGGER IF NOT EXISTS family_scheduled_expiry_valid BEFORE INSERT ON family_scheduled_expiries
    WHEN NOT EXISTS(SELECT 1 FROM family_scheduled_executions e
      JOIN family_scheduled_execution_events a ON a.execution_id=e.id AND a.kind='begin' AND a.created_at=e.created_at
      WHERE e.id=NEW.execution_id AND e.expires_at<=NEW.created_at)
      OR EXISTS(SELECT 1 FROM family_scheduled_results WHERE execution_id=NEW.execution_id)
    BEGIN SELECT RAISE(ABORT,'Scheduled expiry conflicts with execution history'); END;
  CREATE TRIGGER IF NOT EXISTS family_scheduled_expiry_immutable BEFORE UPDATE ON family_scheduled_expiries
    BEGIN SELECT RAISE(ABORT,'Scheduled expiry is immutable'); END;
  CREATE TRIGGER IF NOT EXISTS family_scheduled_expiry_no_delete BEFORE DELETE ON family_scheduled_expiries
    BEGIN SELECT RAISE(ABORT,'Scheduled expiry cannot be deleted'); END;
  CREATE TRIGGER IF NOT EXISTS family_scheduled_result_not_expired BEFORE INSERT ON family_scheduled_results
    WHEN EXISTS(SELECT 1 FROM family_scheduled_expiries WHERE execution_id=NEW.execution_id)
    BEGIN SELECT RAISE(ABORT,'Scheduled execution is terminal'); END;
  CREATE TRIGGER IF NOT EXISTS family_scheduled_dispatch_not_expired BEFORE INSERT ON family_scheduled_dispatches
    WHEN EXISTS(SELECT 1 FROM family_scheduled_expiries WHERE execution_id=NEW.execution_id)
    BEGIN SELECT RAISE(ABORT,'Scheduled execution is terminal'); END;

CREATE TABLE IF NOT EXISTS family_scheduled_interruptions (
    execution_id TEXT PRIMARY KEY REFERENCES family_scheduled_executions(id),
    started_at INTEGER NOT NULL,
    created_at INTEGER NOT NULL CHECK(created_at>=started_at)
  ) STRICT;
  CREATE TRIGGER IF NOT EXISTS family_scheduled_interruption_valid BEFORE INSERT ON family_scheduled_interruptions
    WHEN NOT EXISTS(SELECT 1 FROM family_scheduled_executions e
      JOIN family_scheduled_dispatches d ON d.execution_id=e.id
      JOIN family_scheduled_execution_events a ON a.execution_id=e.id AND a.kind='begin' AND a.created_at=e.created_at
      WHERE e.id=NEW.execution_id AND d.started_at=NEW.started_at AND d.started_at>=e.created_at AND d.started_at<e.expires_at)
      OR EXISTS(SELECT 1 FROM family_scheduled_results WHERE execution_id=NEW.execution_id)
      OR EXISTS(SELECT 1 FROM family_scheduled_expiries WHERE execution_id=NEW.execution_id)
      OR EXISTS(SELECT 1 FROM family_scheduled_execution_events WHERE execution_id=NEW.execution_id AND kind='settle')
    BEGIN SELECT RAISE(ABORT,'Scheduled interruption conflicts with execution history'); END;
  CREATE TRIGGER IF NOT EXISTS family_scheduled_interruption_immutable BEFORE UPDATE ON family_scheduled_interruptions
    BEGIN SELECT RAISE(ABORT,'Scheduled interruption is immutable'); END;
  CREATE TRIGGER IF NOT EXISTS family_scheduled_interruption_no_delete BEFORE DELETE ON family_scheduled_interruptions
    BEGIN SELECT RAISE(ABORT,'Scheduled interruption cannot be deleted'); END;
  CREATE TRIGGER IF NOT EXISTS family_scheduled_result_not_interrupted BEFORE INSERT ON family_scheduled_results
    WHEN EXISTS(SELECT 1 FROM family_scheduled_interruptions WHERE execution_id=NEW.execution_id)
    BEGIN SELECT RAISE(ABORT,'Scheduled execution is terminal'); END;
  CREATE TRIGGER IF NOT EXISTS family_scheduled_expiry_not_interrupted BEFORE INSERT ON family_scheduled_expiries
    WHEN EXISTS(SELECT 1 FROM family_scheduled_interruptions WHERE execution_id=NEW.execution_id)
    BEGIN SELECT RAISE(ABORT,'Scheduled execution is terminal'); END;
  CREATE TRIGGER IF NOT EXISTS family_scheduled_settle_event_not_interrupted BEFORE INSERT ON family_scheduled_execution_events
    WHEN NEW.kind='settle' AND EXISTS(SELECT 1 FROM family_scheduled_interruptions WHERE execution_id=NEW.execution_id)
    BEGIN SELECT RAISE(ABORT,'Scheduled execution is terminal'); END;
  CREATE TRIGGER IF NOT EXISTS family_scheduled_dispatch_not_interrupted BEFORE INSERT ON family_scheduled_dispatches
    WHEN EXISTS(SELECT 1 FROM family_scheduled_interruptions WHERE execution_id=NEW.execution_id)
    BEGIN SELECT RAISE(ABORT,'Scheduled execution is terminal'); END;

CREATE TRIGGER IF NOT EXISTS family_scheduled_settle_event_not_cancelled BEFORE INSERT ON family_scheduled_execution_events
    WHEN NEW.kind='settle' AND EXISTS(SELECT 1 FROM family_scheduled_cancellations WHERE execution_id=NEW.execution_id)
    BEGIN SELECT RAISE(ABORT,'Scheduled execution is cancelled'); END;

CREATE TABLE IF NOT EXISTS family_workspace_files (
    path TEXT PRIMARY KEY,mtime_ms INTEGER NOT NULL,size_bytes INTEGER NOT NULL,indexed_at TEXT NOT NULL
  ) STRICT;
  CREATE VIRTUAL TABLE IF NOT EXISTS family_workspace_fts USING fts5(content,path UNINDEXED,mtime_ms UNINDEXED,size_bytes UNINDEXED);
  CREATE TABLE IF NOT EXISTS family_workspace_index_status (
    scope TEXT PRIMARY KEY,state TEXT NOT NULL,last_indexed_at TEXT,indexed_file_count INTEGER NOT NULL,updated_at TEXT NOT NULL
  ) STRICT;
  CREATE TABLE IF NOT EXISTS family_workspace_index_generation (
    id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL CHECK(revision>=0)
  ) STRICT;
  INSERT OR IGNORE INTO family_workspace_index_generation VALUES (1,0);

CREATE TABLE IF NOT EXISTS family_memory_publications (
    publication_id TEXT PRIMARY KEY,
    owner_user_id TEXT NOT NULL REFERENCES users(id),
    request_id TEXT NOT NULL,
    login_session_id TEXT NOT NULL,
    publisher_username TEXT NOT NULL,
    publisher_display_name TEXT NOT NULL,
    source_chat_jid TEXT NOT NULL,
    source_message_rowid INTEGER NOT NULL,
    source_message_id TEXT NOT NULL,
    source_hash TEXT NOT NULL,
    text TEXT NOT NULL CHECK(length(CAST(text AS BLOB)) BETWEEN 1 AND 16384),
    text_hash TEXT NOT NULL,
    published_at TEXT NOT NULL,
    UNIQUE(owner_user_id,request_id)
  ) STRICT;
  CREATE TABLE IF NOT EXISTS family_memory_withdrawals (
    publication_id TEXT PRIMARY KEY REFERENCES family_memory_publications(publication_id),
    owner_user_id TEXT NOT NULL REFERENCES users(id),
    login_session_id TEXT NOT NULL,
    withdrawn_at TEXT NOT NULL
  ) STRICT;
  CREATE INDEX IF NOT EXISTS family_memory_owner ON family_memory_publications(owner_user_id,published_at,publication_id);
  CREATE INDEX IF NOT EXISTS family_memory_newest ON family_memory_publications(published_at,publication_id);
  CREATE TRIGGER IF NOT EXISTS family_memory_publication_immutable BEFORE UPDATE ON family_memory_publications
    BEGIN SELECT RAISE(ABORT,'Family memory publication is immutable'); END;
  CREATE TRIGGER IF NOT EXISTS family_memory_publication_no_delete BEFORE DELETE ON family_memory_publications
    BEGIN SELECT RAISE(ABORT,'Family memory publication history cannot be deleted'); END;
  CREATE TRIGGER IF NOT EXISTS family_memory_withdrawal_owner BEFORE INSERT ON family_memory_withdrawals
    WHEN NOT EXISTS (SELECT 1 FROM family_memory_publications p WHERE p.publication_id=NEW.publication_id AND p.owner_user_id=NEW.owner_user_id)
    BEGIN SELECT RAISE(ABORT,'Family memory withdrawal requires its publisher'); END;
  CREATE TRIGGER IF NOT EXISTS family_memory_withdrawal_immutable BEFORE UPDATE ON family_memory_withdrawals
    BEGIN SELECT RAISE(ABORT,'Family memory withdrawal is immutable'); END;
  CREATE TRIGGER IF NOT EXISTS family_memory_withdrawal_no_delete BEFORE DELETE ON family_memory_withdrawals
    BEGIN SELECT RAISE(ABORT,'Family memory withdrawal history cannot be deleted'); END;
